local AugerMaker = {}
local PRODUCTS = {
    iron_auger = { name = "Železni sveder", ironCost = 2, woodCost = 2, leatherCost = 1, time = 5, cost = 140, prestige = 2, happiness = 1, description = "Železni sveder za vrtanje v les." },
    bronze_auger = { name = "Bronast sveder", bronzeCost = 2, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 340, prestige = 4, happiness = 2, description = "Bronast sveder za trši material." },
    silver_auger = { name = "Srebrni sveder", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 820, prestige = 9, happiness = 3, description = "Srebrni sveder za precizno vrtanje." },
    gilded_auger = { name = "Pozlačeni sveder", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1750, prestige = 18, happiness = 4, description = "Pozlačeni sveder za dvorne mojstre." },
    jewel_set_auger = { name = "Draguljasti sveder", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 3800, prestige = 33, happiness = 6, description = "Draguljasti sveder za kraljeve mojstre." },
    royal_sovereign_auger = { name = "Kraljevski suvereni sveder", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8200, prestige = 65, happiness = 12, description = "Suvereni sveder z biseri za krono." },
}
local BUILDINGS = {
    auger_workshop = { name = "Vrtalna delavnica", cost = { gold = 320, wood = 170, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    auger_house = { name = "Vrtalna hiša", cost = { gold = 1180, wood = 350, stone = 260, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_auger_atelier = { name = "Mojstrski vrtalni atelje", cost = { gold = 2950, wood = 410, stone = 510, silver = 34, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_boring_palace = { name = "Suverena vrtalna palača", cost = { gold = 12800, wood = 620, stone = 820, gold = 82, jewel = 19 }, upkeep = 250, qualityBonus = 55, prestigeBonus = 50 },
}
AugerMaker.ironStock = 12; AugerMaker.bronzeStock = 10; AugerMaker.woodStock = 14; AugerMaker.leatherStock = 10; AugerMaker.silverStock = 8; AugerMaker.goldStock = 6; AugerMaker.jewelStock = 4; AugerMaker.pearlStock = 4
AugerMaker.productStock = {}; AugerMaker.buildings = {}; AugerMaker.maker = nil; AugerMaker.activeMaking = {}; AugerMaker.totalProducts = 0; AugerMaker.dayTimer = 0
function AugerMaker.init() AugerMaker.ironStock=12; AugerMaker.bronzeStock=10; AugerMaker.woodStock=14; AugerMaker.leatherStock=10; AugerMaker.silverStock=8; AugerMaker.goldStock=6; AugerMaker.jewelStock=4; AugerMaker.pearlStock=4; AugerMaker.productStock={}; AugerMaker.buildings={}; AugerMaker.maker=nil; AugerMaker.activeMaking={}; AugerMaker.totalProducts=0; AugerMaker.dayTimer=0; print("[AugerMaker] Royal Auger Maker System initialized (6 products, 4 buildings)") end
function AugerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; AugerMaker.maker={name=n or ("Svedrar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Svedrar najet: %s (spretnost: %d)",AugerMaker.maker.name,s),"success") end; return true end
function AugerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function AugerMaker.build(id) local ok,e=AugerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(AugerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function AugerMaker.getQualityBonus() local b=0; for _,bd in ipairs(AugerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function AugerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and AugerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and AugerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and AugerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and AugerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and AugerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and AugerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and AugerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and AugerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #AugerMaker.buildings==0 then return false,"Potrebna vrtalna delavnica" end; if not AugerMaker.maker then return false,"Potreben svedrar" end; return true end
function AugerMaker.make(pt,qty) qty=qty or 1; local ok,e=AugerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then AugerMaker.ironStock=AugerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then AugerMaker.bronzeStock=AugerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then AugerMaker.woodStock=AugerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then AugerMaker.leatherStock=AugerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then AugerMaker.silverStock=AugerMaker.silverStock-d.silverCost*qty end; if d.goldCost then AugerMaker.goldStock=AugerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then AugerMaker.jewelStock=AugerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then AugerMaker.pearlStock=AugerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if AugerMaker.maker then t=math.max(1,t-math.floor(AugerMaker.maker.skill/13)) end; table.insert(AugerMaker.activeMaking,{id="auger_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function AugerMaker.completeMaking(m) local q=1.0+(AugerMaker.getQualityBonus()/100); if AugerMaker.maker then q=q+(AugerMaker.maker.skill/140) end; q=math.min(2.5,q); AugerMaker.productStock[m.productType]=(AugerMaker.productStock[m.productType] or 0)+m.quantity; AugerMaker.totalProducts=AugerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if AugerMaker.maker then AugerMaker.maker.itemsMade=AugerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then AugerMaker.maker.skill=math.min(100,AugerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sveder izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"auger.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function AugerMaker.update(dt) if not _G.state then return end; AugerMaker.dayTimer=AugerMaker.dayTimer+dt; if AugerMaker.dayTimer>=30 then AugerMaker.dayTimer=0; for i=#AugerMaker.activeMaking,1,-1 do local m=AugerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then AugerMaker.completeMaking(m); table.remove(AugerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(AugerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if AugerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function AugerMaker.getStats() return {ironStock=AugerMaker.ironStock,bronzeStock=AugerMaker.bronzeStock,woodStock=AugerMaker.woodStock,leatherStock=AugerMaker.leatherStock,silverStock=AugerMaker.silverStock,goldStock=AugerMaker.goldStock,jewelStock=AugerMaker.jewelStock,pearlStock=AugerMaker.pearlStock,productStock=AugerMaker.productStock,numBuildings=#AugerMaker.buildings,hasMaker=AugerMaker.maker~=nil,makerName=AugerMaker.maker and AugerMaker.maker.name or "—",makerSkill=AugerMaker.maker and AugerMaker.maker.skill or 0,activeMaking=#AugerMaker.activeMaking,totalProducts=AugerMaker.totalProducts} end
return AugerMaker
